const body = $json.body ?? $json;
const brief = body.brief ?? {};

const required = ['topic','duration','contentStyle','visualStyle','voiceTone','captionStyle'];
for (const field of required) {
  if (brief[field] === undefined || brief[field] === null || String(brief[field]).trim() === '') {
    throw new Error(`Missing brief.${field}`);
  }
}

const duration = Number(brief.duration);
if (![30, 45, 60, 90].includes(duration)) {
  throw new Error('brief.duration must be 30, 45, 60, or 90');
}

const sceneCount = Math.max(6, Math.min(18, Number(brief.sceneCount ?? Math.ceil(duration / 5))));

const uuidV4 = () => { const bytes = new Uint8Array(16); for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256); bytes[6] = (bytes[6] & 0x0f) | 0x40; bytes[8] = (bytes[8] & 0x3f) | 0x80; return Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('').replace(/^(........)(....)(....)(....)(............)$/, '$1-$2-$3-$4-$5'); };
const jobId = uuidV4();

return [{ json: {
  jobId,
  channelId: body.channelId ?? 'default',
  sessionId: body.sessionId ?? null,
  status: 'queued',
  progress: 0,
  currentStep: 'queued',
  createdAt: new Date().toISOString(),
  brief: {
    topic: String(brief.topic).trim(),
    duration,
    sceneCount,
    language: String(brief.language ?? 'English').trim(),
    contentStyle: String(brief.contentStyle).trim(),
    visualStyle: String(brief.visualStyle).trim(),
    voiceTone: String(brief.voiceTone).trim(),
    captionStyle: String(brief.captionStyle ?? 'bold highlighted words').trim(),
    aspectRatio: '9:16'
  }
}}];

const job = $('Validate and Create Job').first().json;
return [{ json: {
  success: true,
  jobId: job.jobId,
  status: 'queued'
} }];
